package com.deardiary.privateapp;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;
final class UpdateSheet extends LinearLayout{
 final TextView status;final Button update;final ProgressBar progress;private final int ink,muted;private final boolean dark;
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 UpdateSheet(Context c,boolean night,JSONObject release,Runnable action){super(c);dark=night;ink=Color.parseColor(dark?"#F3E8ED":"#594553");muted=Color.parseColor(dark?"#C4B1BC":"#8B7781");setOrientation(VERTICAL);setPadding(dp(24),dp(26),dp(24),dp(24));GradientDrawable background=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.parseColor(dark?"#211A27":"#FFF9F6"),Color.parseColor(dark?"#302434":"#F4E8F0")});background.setCornerRadius(dp(30));setBackground(background);
  LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(c);icon.setImageResource(R.drawable.app_icon);header.addView(icon,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout heading=new LinearLayout(c);heading.setOrientation(VERTICAL);heading.setPadding(dp(14),0,0,0);heading.addView(text("DEAR DIARY",11,muted));TextView title=text("A little refresh",27,ink);title.setTypeface(Typeface.create("serif",Typeface.NORMAL));heading.addView(title);header.addView(heading,new LinearLayout.LayoutParams(-1,-2));addView(header);
  TextView version=text("VERSION "+release.optString("version")+"  ·  "+String.format(java.util.Locale.US,"%.1f MB",release.optLong("bytes")/1000000d),12,Color.parseColor(dark?"#E6AFC2":"#A97087"));version.setPadding(0,dp(18),0,dp(22));addView(version);TextView label=text("What's new",19,ink);label.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));addView(label);
  ScrollView scroll=new ScrollView(c);scroll.setFillViewport(false);LinearLayout cards=new LinearLayout(c);cards.setOrientation(VERTICAL);cards.setPadding(0,dp(12),0,dp(10));String[] paragraphs=release.optString("notes").split("\\n\\s*\\n");for(int i=0;i<paragraphs.length;i++){if(paragraphs[i].trim().isEmpty())continue;TextView card=text(paragraphs[i].trim(),14,ink);card.setLineSpacing(dp(5),1);card.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable bg=new GradientDrawable();bg.setCornerRadius(dp(18));bg.setColor(Color.parseColor(dark?"#3A2E3E":"#FFFFFF"));card.setBackground(bg);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(10);cards.addView(card,cp);}scroll.addView(cards);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,0,1);sp.bottomMargin=dp(10);addView(scroll,sp);
  TextView secure=text("Private release · checked before install",12,Color.parseColor(dark?"#C2D3BC":"#65815E"));addView(secure);TextView explain=text("Your diary stays in this app. Android will ask you to confirm Install.",12,muted);explain.setLineSpacing(dp(3),1);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,-2);ep.topMargin=dp(7);ep.bottomMargin=dp(12);addView(explain,ep);
  progress=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(Color.parseColor(dark?"#E6AFC2":"#A97087")));progress.setVisibility(GONE);addView(progress,new LinearLayout.LayoutParams(-1,dp(5)));
  status=text("Ready when you are",12,muted);status.setPadding(0,dp(8),0,dp(12));addView(status);update=new Button(c);update.setText("Update");update.setTextSize(15);update.setAllCaps(false);update.setTextColor(Color.parseColor(dark?"#39212F":"#FFFFFF"));GradientDrawable button=new GradientDrawable();button.setCornerRadius(dp(18));button.setColor(Color.parseColor(dark?"#E6AFC2":"#A97087"));update.setBackground(button);update.setOnClickListener(v->action.run());addView(update,new LinearLayout.LayoutParams(-1,dp(54)));TextView later=text("You can close this and update later",11,muted);later.setGravity(Gravity.CENTER);later.setPadding(0,dp(12),0,0);addView(later);
 }
 private TextView text(String value,int size,int color){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 void downloading(int percent){progress.setVisibility(VISIBLE);progress.setIndeterminate(false);progress.setProgress(percent);status.setText("Downloading securely · "+percent+"%");update.setText("Downloading...");update.setEnabled(false);}
}
